&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Les arch&#233;types de sanguin&lt;a class=&quot;headeranchor&quot; id=&quot;Les_arch&#233;types_de_sanguin_0&quot; href=&quot;#Les_arch&#233;types_de_sanguin_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&amp;nbsp;Retour &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Sanguin.html&quot; title=&quot;Le sanguin&quot;&gt;classe&lt;/a&gt;.
&lt;ul style=&quot;margin-top:2px&quot;&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cavalier-Sanguin-(Sanguin).html&quot; title=&quot;Cavalier sanguin&quot;&gt;Cavalier sanguin&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;voreur-De-Sorts-(Sanguin).html&quot; title=&quot;D&#233;voreur de sorts&quot;&gt;D&#233;voreur de sorts&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Interm&#233;diaire-Sanguin-(Sanguin).html&quot; title=&quot;Interm&#233;diaire sanguin&quot;&gt;Interm&#233;diaire sanguin&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;M&#233;tamorphe-Sanguin-(Sanguin).html&quot; title=&quot;M&#233;tamorphe sanguin&quot;&gt;M&#233;tamorphe sanguin&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Primitif-(Sanguin).html&quot; title=&quot;Primitif&quot;&gt;Primitif&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sangacier-(Sanguin).html&quot; title=&quot;Sangacier&quot;&gt;Sangacier&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sanguin-Au-Sang-M&#234;l&#233;-(Sanguin).html&quot; title=&quot;Sanguin au sang m&#234;l&#233;&quot;&gt;Sanguin au sang m&#234;l&#233;&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sanguin-Intouchable-(Sanguin).html&quot; title=&quot;Sanguin intouchable&quot;&gt;Sanguin intouchable&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sanguin-M&#233;tamagique-(Sanguin).html&quot; title=&quot;Sanguin m&#233;tamagique&quot;&gt;Sanguin m&#233;tamagique&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sanguin-Pulsionnel-(Sanguin).html&quot; title=&quot;Sanguin pulsionnel&quot;&gt;Sanguin pulsionnel&lt;/a&gt; (&lt;i&gt;OO&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sanguin-Verdoyant-(Sanguin).html&quot; title=&quot;Sanguin verdoyant&quot;&gt;Sanguin verdoyant&lt;/a&gt; (MCA)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Origines occultes (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Occult Origins/Origines occultes ; /!\ Traduit par la communaut&#233; /!\&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoOO.png&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;i&gt;Un sanguin pulsionnel n&#39;a pas de marque surnaturelle dans son sang, mais tire ses pouvoirs de ses &#233;motions brutes.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Avatar atavique (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Avatar_atavique_Sur_0&quot; href=&quot;#Avatar_atavique_Sur_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un sanguin pulsionnel choisit une &#233;motion dominante de fant&#244;me pour d&#233;finir ce qui le compose : col&#232;re, d&#233;votion, d&#233;sespoir, haine, jalousie, peur, remords, ou z&#232;le. Au niveau 1, il gagne le don &lt;a class=&quot;pagelink&quot; href=&quot;Talent.html&quot; title=&quot;Talent&quot;&gt;Talent&lt;/a&gt; pour l&#39;une des comp&#233;tences associ&#233;es &#224; sa focalisation atavique.
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Col&#232;re.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Survie.html&quot; title=&quot;Survie&quot;&gt;Survie&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;D&#233;vouement.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Psychologie.html&quot; title=&quot;Psychologie&quot;&gt;Psychologie&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;D&#233;sespoir.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Peur.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Haine.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Jalousie.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Estimation.html&quot; title=&quot;Estimation&quot;&gt;Estimation&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;Bluff&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Remords.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Psychologie.html&quot; title=&quot;Psychologie&quot;&gt;Psychologie&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Z&#232;le.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Survie.html&quot; title=&quot;Survie&quot;&gt;Survie&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;Lorsqu&#39;un sanguin pulsionnel entre en &lt;a class=&quot;pagelink&quot; href=&quot;Sanguin.html#RAGESANGUINE&quot; title=&quot;Le sanguin&quot;&gt;rage sanguine&lt;/a&gt;, il gagne des pouvoirs suppl&#233;mentaires comme s&#39;il &#233;tait un &lt;a class=&quot;pagelink&quot; href=&quot;Fant&#244;mes-(Spirite).html&quot; title=&quot;Le fant&#244;me du spirite&quot;&gt;fant&#244;me de spirite&lt;/a&gt; avec l&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Fant&#244;mes-(Spirite).html#EMOTIONDOMINANTE&quot; title=&quot;Le fant&#244;me du spirite&quot;&gt;&#233;motion dominante&lt;/a&gt; qu&#39;il a choisi comme focalisation atavique. Il est consid&#233;r&#233; comme &#233;tant le fant&#244;me et le &lt;a class=&quot;pagelink&quot; href=&quot;Spirite.html&quot; title=&quot;Le spirite&quot;&gt;spirite&lt;/a&gt; pour les effets affectant l&#39;un ou l&#39;autre, comme le combat du vigilant d’un fant&#244;me de &lt;a class=&quot;pagelink&quot; href=&quot;Fant&#244;mes-(Spirite).html#DEVOUEMENT&quot; title=&quot;Le fant&#244;me du spirite&quot;&gt;d&#233;vouement&lt;/a&gt;, et traite son niveau de &lt;a class=&quot;pagelink&quot; href=&quot;Sanguin.html&quot; title=&quot;Le sanguin&quot;&gt;sanguin&lt;/a&gt; comme son niveau de spirite et comme ses d&#233;s de vie de fant&#244;me pour d&#233;terminer le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; des &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; des capacit&#233;s obtenues. Cette capacit&#233; ne permet pas au sanguin pulsionnel de devenir intangible.&lt;br /&gt;&lt;br /&gt;Au niveau 4, le sanguin pulsionnel gagne &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;flexes-Surhumains.html&quot; title=&quot;R&#233;flexes surhumains&quot;&gt;R&#233;flexes surhumains&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Vigueur-Surhumaine.html&quot; title=&quot;Vigueur surhumaine&quot;&gt;Vigueur surhumaine&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Volont&#233;-De-Fer.html&quot; title=&quot;Volont&#233; de fer&quot;&gt;Volont&#233; de fer&lt;/a&gt; comme don suppl&#233;mentaire.&lt;br /&gt;&lt;br /&gt;Au niveau 8, le sanguin pulsionnel peut m&#233;diter pendant 1 heure pour changer sa focalisation atavique pendant les prochaines 24 heures ou jusqu&#39;&#224; ce qu&#39;il d&#233;cide de retourner &#224; sa focalisation atavique permanente par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Libre.html&quot; title=&quot;Action libre&quot;&gt;action libre&lt;/a&gt;. Lorsqu&#39;il change sa focalisation, il perd le don &lt;a class=&quot;pagelink&quot; href=&quot;Talent.html&quot; title=&quot;Talent&quot;&gt;Talent&lt;/a&gt; et le don gagn&#233; au niveau 4 gr&#226;ce &#224; cette capacit&#233;, et il obtient les pouvoirs de sa nouvelle focalisation atavique comme si son niveau de &lt;a class=&quot;pagelink&quot; href=&quot;Spirite.html&quot; title=&quot;Le spirite&quot;&gt;spirite&lt;/a&gt; et ses d&#233;s de vie de &lt;a class=&quot;pagelink&quot; href=&quot;Fant&#244;mes-(Spirite).html&quot; title=&quot;Le fant&#244;me du spirite&quot;&gt;fant&#244;me&lt;/a&gt; &#233;taient inf&#233;rieurs de 3.&lt;br /&gt;&lt;br /&gt;Au niveau 12, le sanguin pulsionnel obtient le don &lt;a class=&quot;pagelink&quot; href=&quot;Talent.html&quot; title=&quot;Talent&quot;&gt;Talent&lt;/a&gt; pour les deux comp&#233;tences associ&#233;es &#224; sa focalisation atavique. Si une situation lui fait perdre l&#39;un de ses dons Talent, il perd les deux.&lt;br /&gt;&lt;br /&gt;Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Sanguin.html#LIGNAGE&quot; title=&quot;Le sanguin&quot;&gt;lignage&lt;/a&gt;, tous les &lt;a class=&quot;pagelink&quot; href=&quot;Sanguin.html#LIGNAGE&quot; title=&quot;Le sanguin&quot;&gt;sorts de lignage&lt;/a&gt; et tous les &lt;a class=&quot;pagelink&quot; href=&quot;Sanguin.html#LIGNAGE&quot; title=&quot;Le sanguin&quot;&gt;pouvoirs de lignage&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Lanceur de sorts atavique&lt;a class=&quot;headeranchor&quot; id=&quot;Lanceur_de_sorts_atavique_1&quot; href=&quot;#Lanceur_de_sorts_atavique_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 4, les sorts de sanguin d&#39;un sanguin pulsionnel sont trait&#233;s comme des &lt;a class=&quot;pagelink&quot; href=&quot;La-Magie-Psychique.html&quot; title=&quot;La magie psychique&quot;&gt;sorts psychiques&lt;/a&gt;. La &lt;a class=&quot;pagelink&quot; href=&quot;Sanguin.html#RAGESANGUINE&quot; title=&quot;Le sanguin&quot;&gt;rage sanguine&lt;/a&gt; du sanguin ne l&#39;emp&#234;che pas de lancer des sorts &#224; composante &#233;motionnelle, et il est consid&#233;r&#233; comme un lanceur de sorts psychiques pour remplir les conditions (comme celles requises aux &lt;a class=&quot;pagelink&quot; href=&quot;Duels-Psychiques.html&quot; title=&quot;Les duels psychiques&quot;&gt;duels psychiques&lt;/a&gt; et aux &lt;a class=&quot;pagelink&quot; href=&quot;Extensions-De-Comp&#233;tences-Occultes.html&quot; title=&quot;Extensions de comp&#233;tences occultes&quot;&gt;extensions de comp&#233;tences occultes&lt;/a&gt;). Cette capacit&#233; modifie les &lt;a class=&quot;pagelink&quot; href=&quot;Sanguin.html#SORTS&quot; title=&quot;Le sanguin&quot;&gt;sorts du sanguin&lt;/a&gt; et remplace &lt;a class=&quot;pagelink&quot; href=&quot;Sanguin.html#DISPENSE&quot; title=&quot;Le sanguin&quot;&gt;dispense de composantes mat&#233;rielles&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Dons suppl&#233;mentaires&lt;a class=&quot;headeranchor&quot; id=&quot;Dons_suppl&#233;mentaires_2&quot; href=&quot;#Dons_suppl&#233;mentaires_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 6 et tous les 3 niveaux de sanguin par la suite, un sanguin pulsionnel peut choisir un des dons suivants comme don suppl&#233;mentaire: &lt;a class=&quot;pagelink&quot; href=&quot;Combattant-Psychique.html&quot; title=&quot;Combattant psychique&quot;&gt;Combattant psychique&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Concentration-Rageuse.html&quot; title=&quot;Concentration rageuse&quot;&gt;Concentration rageuse&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;fenseur-Psychique.html&quot; title=&quot;D&#233;fenseur psychique&quot;&gt;D&#233;fenseur psychique&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;&#201;cole-Renforc&#233;e.html&quot; title=&quot;&#201;cole renforc&#233;e&quot;&gt;&#201;cole renforc&#233;e&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Efficacit&#233;-Des-Sorts-Accrue.html&quot; title=&quot;Efficacit&#233; des sorts accrue&quot;&gt;Efficacit&#233; des sorts accrue&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Empathe.html&quot; title=&quot;Empathe&quot;&gt;Empathe&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Gu&#233;rison-Psychique.html&quot; title=&quot;Gu&#233;rison psychique&quot;&gt;Gu&#233;rison psychique&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Maestro-Psychique.html&quot; title=&quot;Maestro psychique&quot;&gt;Maestro psychique&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Magie-De-Guerre.html&quot; title=&quot;Magie de guerre&quot;&gt;Magie de guerre&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Rage-Suppl&#233;mentaire.html&quot; title=&quot;Rage suppl&#233;mentaire&quot;&gt;Rage suppl&#233;mentaire&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Sort-Intuitif.html&quot; title=&quot;Sort intuitif&quot;&gt;Sort intuitif&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Sort-Logique.html&quot; title=&quot;Sort logique&quot;&gt;Sort logique&lt;/a&gt;, ou &lt;a class=&quot;pagelink&quot; href=&quot;Virtuose-Psychique.html&quot; title=&quot;Virtuose psychique&quot;&gt;Virtuose psychique&lt;/a&gt;. Cette capacit&#233; remplace tous les &lt;a class=&quot;pagelink&quot; href=&quot;Sanguin.html#LIGNAGE&quot; title=&quot;Le sanguin&quot;&gt;dons de lignage&lt;/a&gt;.
